#include "native_utils.h"
#include <ATen/MemoryOverlap.h>
#include <ATen/native/Resize.h>
#include <torch/library.h>
#include <cmath>
#include <numeric>
namespace torch_vulkan::ops {namespace {
using namespace native;
using Range=std::optional<at::ArrayRef<double>>;
void histogram_input(const at::Tensor& x){TORCH_CHECK(x.dim()>=2,"torch.histogramdd: input tensor should have at least 2 dimensions, but got ",x.dim());TORCH_CHECK(x.scalar_type()==at::kFloat,"Vulkan histogram requires FP32 input");}
void histogram_check(const at::Tensor& x,at::TensorList edges,const std::optional<at::Tensor>& weight){
 histogram_input(x);auto dimensions=x.size(-1);TORCH_CHECK(int64_t(edges.size())==dimensions,"torch.histogramdd: expected ",dimensions," sequences of bin edges for a ",dimensions,"-dimensional histogram but got ",edges.size());
 for(int64_t d=0;d<dimensions;d++){const auto& edge=edges[d];TORCH_CHECK(edge.scalar_type()==x.scalar_type(),"torch.histogramdd: input tensor and bins tensors should have the same dtype");TORCH_CHECK(edge.device()==x.device(),"histogram bins must be on the input device");TORCH_CHECK(edge.dim()==1,"torch.histogramdd: bins tensor should have one dimension, but got ",edge.dim()," dimensions in the bins tensor for dimension ",d);TORCH_CHECK(edge.numel()>0,"torch.histogramdd: bins tensor should have at least 1 element, but got 0 elements in the bins tensor for dimension ",d);TORCH_CHECK(edge.numel()>1,"torch.histogram(): bins must be > 0, but got 0 for dimension ",d);}
 if(weight&&weight->defined()){TORCH_CHECK(weight->scalar_type()==x.scalar_type(),"torch.histogramdd: if weight tensor is provided, input tensor and weight tensor should have the same dtype");TORCH_CHECK(weight->device()==x.device(),"histogram weight must be on the input device");auto shape=x.sizes().vec();shape.pop_back();auto weights=weight->sizes().vec();if(weights.empty())weights={1};TORCH_CHECK(shape==weights,"torch.histogramdd: if weight tensor is provided it should have the same shape as the input tensor excluding its innermost dimension, but got input with shape ",x.sizes()," and weight with shape ",weight->sizes());}
}
std::vector<at::Tensor> histogram_edges(const at::Tensor& x,at::IntArrayRef bins,Range range,const std::optional<at::Tensor>&,bool){
 histogram_input(x);auto dimensions=x.size(-1);TORCH_CHECK(int64_t(bins.size())==dimensions,"histogramdd: The size of bins must be equal to the innermost dimension of the input.");if(range)TORCH_CHECK(int64_t(range->size())==2*dimensions,"torch.histogramdd: for a ",dimensions,"-dimensional histogram range should have ",2*dimensions," elements, but got ",range->size());
 int64_t rows=1;for(int64_t d=0;d<x.dim()-1;d++)rows*=x.size(d);auto values=x.reshape({rows,dimensions});std::vector<at::Tensor> edges;
 for(int64_t d=0;d<dimensions;d++){TORCH_CHECK(bins[d]>0,"torch.histogram(): bins must be > 0, but got ",bins[d]," for dimension ",d);double left=0,right=1;if(range){left=(*range)[2*d];right=(*range)[2*d+1];}else if(rows){auto column=values.select(1,d);auto extrema=at::aminmax(column);left=std::get<0>(extrema).cpu().item<double>();right=std::get<1>(extrema).cpu().item<double>();}TORCH_CHECK(std::isfinite(left)&&std::isfinite(right),"torch.histogramdd: dimension ",d,"'s range [",left,", ",right,"] is not finite");TORCH_CHECK(left<=right,"torch.histogramdd: min should not exceed max, but got min ",left," max ",right," for dimension ",d);if(left==right){left-=.5;right+=.5;}edges.push_back(at::linspace(left,right,bins[d]+1,x.options()));}return edges;
}
at::Tensor histogram_from_edges(const at::Tensor& x,at::TensorList edges,const std::optional<at::Tensor>& weight,bool density){
 histogram_check(x,edges,weight);auto dimensions=x.size(-1);int64_t rows=1,total=1;for(int64_t d=0;d<x.dim()-1;d++)rows*=x.size(d);std::vector<int64_t> shape;for(const auto& edge:edges){auto n=edge.numel()-1;TORCH_CHECK(total<=INT64_MAX/n,"histogram output shape overflows");total*=n;shape.push_back(n);}u32(total);
 auto flat=x.reshape({rows,dimensions});auto indices=at::zeros({rows},x.options().dtype(at::kLong));auto valid=at::ones({rows},x.options().dtype(at::kBool));
 for(int64_t d=0;d<dimensions;d++){auto values=flat.select(1,d);const auto& edge=edges[d];auto n=edge.numel()-1;auto position=at::searchsorted(edge,values,false,true).sub(1);position=at::where(position.eq(n),position.sub(1),position);valid=at::logical_and(valid,at::logical_and(values.ge(edge.select(0,0)),values.le(edge.select(0,n))));indices=indices.mul(n).add(position);}
 at::Tensor hist;if(!dimensions||!rows)hist=at::zeros(shape,x.options());else{auto selected=at::masked_select(indices,valid);std::optional<at::Tensor> weights;if(weight&&weight->defined())weights=at::masked_select(weight->reshape({rows}),valid);hist=at::bincount(selected,weights,total).to(at::kFloat).reshape(shape);}
 if(density){hist=hist.div(hist.sum());for(int64_t d=0;d<dimensions;d++){std::vector<int64_t> broadcast(dimensions,1);broadcast[d]=shape[d];auto widths=edges[d].narrow(0,1,shape[d]).sub(edges[d].narrow(0,0,shape[d]));hist=hist.div(widths.reshape(broadcast));}}return hist;
}
at::Tensor histogram_from_counts(const at::Tensor& x,at::IntArrayRef bins,Range range,const std::optional<at::Tensor>& weight,bool density){auto edges=histogram_edges(x,bins,range,weight,density);return histogram_from_edges(x,edges,weight,density);}
std::optional<at::Tensor> histogram_weights(const std::optional<at::Tensor>& weight){if(weight&&weight->defined())return weight->reshape({weight->numel()});return std::nullopt;}
std::tuple<at::Tensor,at::Tensor> histogram_tensor(const at::Tensor& x,const at::Tensor& edges,const std::optional<at::Tensor>& weight,bool density){auto values=x.reshape({x.numel(),1});return {histogram_from_edges(values,{edges},histogram_weights(weight),density),edges.clone()};}
std::tuple<at::Tensor,at::Tensor> histogram_count(const at::Tensor& x,int64_t bins,Range range,const std::optional<at::Tensor>& weight,bool density){auto values=x.reshape({x.numel(),1});auto edges=histogram_edges(values,{bins},range,weight,density);return {histogram_from_edges(values,edges,histogram_weights(weight),density),edges[0]};}
at::Tensor histc_native(const at::Tensor& x,int64_t bins,const at::Scalar& minimum,const at::Scalar& maximum){
 TORCH_CHECK(x.scalar_type()==at::kFloat,"Vulkan histc requires FP32 input");TORCH_CHECK(bins>0,"torch.histogram(): bins must be > 0, but got ",bins," for dimension 0");u32(bins);double left=minimum.toDouble(),right=maximum.toDouble();if(left==right&&x.numel()){auto extrema=at::aminmax(x);left=std::get<0>(extrema).cpu().item<double>();right=std::get<1>(extrema).cpu().item<double>();}if(left==right){left=std::min(double(std::nextafter(float(left),-INFINITY)),left-1);right=std::max(double(std::nextafter(float(right),INFINITY)),right+1);}TORCH_CHECK(std::isfinite(left)&&std::isfinite(right),"torch.histc: range of [",left,", ",right,"] is not finite");TORCH_CHECK(left<right,"torch.histc: max must be larger than min");
 auto values=x.flatten();auto valid=at::logical_and(values.ge(float(left)),values.le(float(right)));auto position=values.sub(float(left)).mul(bins).div(float(right)-float(left)).to(at::kLong);position=at::where(position.eq(bins),position.sub(1),position);auto selected=at::masked_select(position,valid);return at::bincount(selected,std::nullopt,bins).to(at::kFloat);
}
void histogram_edges_out(const at::Tensor& x,at::IntArrayRef bins,Range range,const std::optional<at::Tensor>& weight,bool density,at::TensorList out){auto result=histogram_edges(x,bins,range,weight,density);TORCH_CHECK(out.size()==result.size(),"histogram bin edges output count mismatch");for(size_t d=0;d<out.size();d++){auto target=out[d];TORCH_CHECK(target.device()==x.device()&&target.scalar_type()==x.scalar_type(),"histogram bin edges output dtype/device mismatch");at::assert_no_internal_overlap(target);at::native::resize_output(target,result[d].sizes());target.copy_(result[d]);}}
}
TORCH_LIBRARY_IMPL(aten,PrivateUse1,m){m.impl("histogram.bins_tensor",&histogram_tensor);m.impl("histogram.bin_ct",&histogram_count);m.impl("histc",&histc_native);m.impl("_histogramdd_bin_edges",&histogram_edges);m.impl("_histogramdd_bin_edges.out",&histogram_edges_out);m.impl("_histogramdd_from_bin_cts",&histogram_from_counts);m.impl("_histogramdd_from_bin_tensors",&histogram_from_edges);}
}
